CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('SUPERADMIN','DIRECAO','SECRETARIA_CENTRAL','SECRETARIA_ATENDIMENTO','PROFESSOR','ALUNO','RESPONSAVEL');
CREATE TYPE shift_type AS ENUM ('MORNING','AFTERNOON','EVENING','FULL_TIME');
CREATE TYPE calendar_type AS ENUM ('ACADEMIC','ADMINISTRATIVE','EVENTS');
CREATE TYPE enrollment_status AS ENUM ('ACTIVE','TRANSFERRED','CANCELLED','COMPLETED');
CREATE TYPE attendance_status AS ENUM ('PRESENT','ABSENT','JUSTIFIED');

CREATE TABLE schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(180) NOT NULL, legal_name varchar(180), cnpj varchar(30) UNIQUE, inep_code varchar(30), email varchar(180), phone varchar(40), address varchar(250), city varchar(100), state char(2), zip_code varchar(15), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id), name varchar(180) NOT NULL, email varchar(180) UNIQUE NOT NULL, password_hash text NOT NULL, role user_role NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_users_school ON users(school_id);
CREATE TABLE academic_years (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(50) NOT NULL, year integer NOT NULL, start_date date NOT NULL, end_date date NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(school_id,year));
CREATE TABLE grade_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, name varchar(120) NOT NULL, education_level varchar(80) NOT NULL, sequence integer NOT NULL);
CREATE TABLE subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, name varchar(120) NOT NULL, code varchar(30), active boolean NOT NULL DEFAULT true);
CREATE TABLE curriculum_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, grade_level_id uuid NOT NULL REFERENCES grade_levels(id), name varchar(180) NOT NULL, description text, is_default boolean NOT NULL DEFAULT false);
CREATE TABLE curriculum_template_subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES curriculum_templates(id) ON DELETE CASCADE, subject_id uuid NOT NULL REFERENCES subjects(id), weekly_hours numeric(5,2) NOT NULL, annual_hours numeric(6,2) NOT NULL, weekly_classes integer NOT NULL, UNIQUE(template_id,subject_id));
CREATE TABLE classrooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, academic_year_id uuid NOT NULL REFERENCES academic_years(id), grade_level_id uuid NOT NULL REFERENCES grade_levels(id), curriculum_template_id uuid REFERENCES curriculum_templates(id), name varchar(80) NOT NULL, shift shift_type NOT NULL, room varchar(50), capacity integer, active boolean NOT NULL DEFAULT true);
CREATE INDEX idx_classrooms_school ON classrooms(school_id);
CREATE TABLE class_subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), classroom_id uuid NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE, subject_id uuid NOT NULL REFERENCES subjects(id), weekly_hours numeric(5,2) NOT NULL, annual_hours numeric(6,2) NOT NULL, weekly_classes integer NOT NULL, UNIQUE(classroom_id,subject_id));
CREATE TABLE teachers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, user_id uuid UNIQUE NOT NULL REFERENCES users(id), registration varchar(50));
CREATE TABLE class_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), classroom_id uuid NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE, class_subject_id uuid NOT NULL REFERENCES class_subjects(id), teacher_id uuid REFERENCES teachers(id), weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 5), period integer NOT NULL CHECK(period > 0), start_time varchar(5) NOT NULL, end_time varchar(5) NOT NULL, room varchar(50), UNIQUE(classroom_id,weekday,period));
CREATE TABLE students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, user_id uuid UNIQUE REFERENCES users(id), registration varchar(50) NOT NULL, name varchar(180) NOT NULL, birth_date date, cpf varchar(20), UNIQUE(school_id,registration));
CREATE TABLE enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id), classroom_id uuid NOT NULL REFERENCES classrooms(id), academic_year_id uuid NOT NULL REFERENCES academic_years(id), enrollment_number varchar(60) NOT NULL, status enrollment_status NOT NULL DEFAULT 'ACTIVE', enrollment_date timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,enrollment_number));
CREATE TABLE calendars (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, academic_year_id uuid NOT NULL REFERENCES academic_years(id), type calendar_type NOT NULL, name varchar(180) NOT NULL, description text, active boolean NOT NULL DEFAULT true, UNIQUE(school_id,academic_year_id,type));
CREATE TABLE calendar_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), calendar_id uuid NOT NULL REFERENCES calendars(id) ON DELETE CASCADE, title varchar(180) NOT NULL, description text, event_date date NOT NULL, end_date date, event_type varchar(80), all_day boolean NOT NULL DEFAULT true, location varchar(180));
CREATE INDEX idx_calendar_events ON calendar_events(calendar_id,event_date);
CREATE TABLE assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, classroom_id uuid NOT NULL REFERENCES classrooms(id), class_subject_id uuid NOT NULL REFERENCES class_subjects(id), teacher_id uuid NOT NULL REFERENCES teachers(id), academic_period varchar(40) NOT NULL, name varchar(120) NOT NULL, max_score numeric(6,2) NOT NULL, assessment_date date NOT NULL);
CREATE TABLE grades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id), score numeric(6,2) NOT NULL, observation text, UNIQUE(assessment_id,student_id));
CREATE TABLE attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id), classroom_id uuid NOT NULL REFERENCES classrooms(id), class_subject_id uuid NOT NULL REFERENCES class_subjects(id), teacher_id uuid NOT NULL REFERENCES teachers(id), attendance_date date NOT NULL, period integer NOT NULL, status attendance_status NOT NULL);
CREATE INDEX idx_attendance_student ON attendance(school_id,student_id,attendance_date);

CREATE TABLE medical_certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, start_date date NOT NULL, end_date date NOT NULL, reason text, document_number varchar(80), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(end_date >= start_date));
CREATE INDEX idx_medical_certificates_student ON medical_certificates(school_id,student_id,start_date,end_date);

-- ================= RECURSOS HUMANOS (RH) =================
CREATE TYPE hr_regime AS ENUM ('MENSALISTA','HORISTA');
CREATE TYPE hr_employee_status AS ENUM ('ATIVO','AFASTADO','DESLIGADO');
CREATE TYPE hr_job_status AS ENUM ('ABERTA','FECHADA');
CREATE TYPE hr_candidate_status AS ENUM ('TRIAGEM','ENTREVISTA','APROVADO','REPROVADO','CONTRATADO');

CREATE TABLE hr_job_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, sector varchar(80), employment_type varchar(40), description text, status hr_job_status NOT NULL DEFAULT 'ABERTA', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hr_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, job_id uuid NOT NULL REFERENCES hr_job_postings(id) ON DELETE CASCADE, name varchar(180) NOT NULL, contact varchar(180), status hr_candidate_status NOT NULL DEFAULT 'TRIAGEM', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hr_substitutes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(180) NOT NULL, subject varchar(120), phone varchar(40), availability varchar(80), status varchar(30) NOT NULL DEFAULT 'Disponível');
CREATE TABLE hr_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, candidate_id uuid REFERENCES hr_candidates(id), name varchar(180) NOT NULL, role varchar(120), employment_type varchar(40), regime hr_regime NOT NULL DEFAULT 'MENSALISTA', admission_date date NOT NULL, salary numeric(12,2) NOT NULL DEFAULT 0, weekly_hours numeric(6,2), hourly_rate numeric(10,2), status hr_employee_status NOT NULL DEFAULT 'ATIVO', has_system_access boolean NOT NULL DEFAULT false);
CREATE INDEX idx_hr_employees_school ON hr_employees(school_id,status);
CREATE TABLE hr_payroll_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, run_date date NOT NULL, employee_count integer NOT NULL, total_amount numeric(14,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hr_benefits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE, benefit_type varchar(80) NOT NULL, description text, monthly_value numeric(10,2) NOT NULL DEFAULT 0, status varchar(30) NOT NULL DEFAULT 'Ativo');
CREATE TABLE hr_leaves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE, leave_type varchar(80) NOT NULL, start_date date NOT NULL, end_date date, notes text, status varchar(30) NOT NULL DEFAULT 'Em andamento', CHECK(end_date IS NULL OR end_date >= start_date));
CREATE INDEX idx_hr_leaves_employee ON hr_leaves(school_id,employee_id,status);
CREATE TABLE hr_terminations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE, termination_date date NOT NULL, reason varchar(120), severance_amount numeric(12,2) DEFAULT 0, status varchar(30) NOT NULL DEFAULT 'Calculada');
CREATE TABLE hr_trainings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, training_type varchar(80), training_date date NOT NULL, participants integer DEFAULT 0, notes text, status varchar(30) NOT NULL DEFAULT 'Planejado');
CREATE TABLE hr_performance_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE, period varchar(60) NOT NULL, coordination_score numeric(4,1), self_evaluation_score numeric(4,1), feedback_score numeric(4,1), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hr_career_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE, career_level varchar(80), education_level varchar(60), years_of_service integer DEFAULT 0, next_progression varchar(180), status varchar(30) NOT NULL DEFAULT 'Em dia');
CREATE TABLE hr_climate_surveys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, survey_date date NOT NULL, respondents integer DEFAULT 0, avg_score numeric(4,1), notes text);
CREATE TABLE hr_wellbeing_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, action_type varchar(80), action_date date, notes text, status varchar(30) NOT NULL DEFAULT 'Planejado');
CREATE TABLE hr_safety_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, employee_id uuid REFERENCES hr_employees(id) ON DELETE CASCADE, exam_type varchar(80) NOT NULL, record_date date NOT NULL, due_date date, status varchar(30) NOT NULL DEFAULT 'Agendado');
CREATE TABLE hr_unions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(180) NOT NULL, category varchar(80), cct_validity date, notes text);
CREATE TABLE hr_lgpd_compliance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, item varchar(180) NOT NULL, responsible varchar(120), status varchar(30) NOT NULL DEFAULT 'Pendente', notes text);
CREATE TABLE hr_ethics_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, protocol varchar(40) UNIQUE NOT NULL, category varchar(80), notes text NOT NULL, status varchar(30) NOT NULL DEFAULT 'Em apuração', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hr_interns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(180) NOT NULL, course varchar(150), institution varchar(150), supervisor varchar(150), start_date date, end_date date, status varchar(30) NOT NULL DEFAULT 'Ativo');

-- ================= DIREÇÃO — ESTRUTURA, ADMINISTRAÇÃO, COMUNICAÇÃO =================
CREATE TABLE institution_spaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(180) NOT NULL, space_type varchar(60) NOT NULL, capacity integer, resources text, status varchar(30) NOT NULL DEFAULT 'Disponível');
CREATE TABLE asset_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(180) NOT NULL, category varchar(60), quantity integer NOT NULL DEFAULT 1, location varchar(150), status varchar(30) NOT NULL DEFAULT 'Em uso');
CREATE TABLE announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, audience varchar(60) NOT NULL DEFAULT 'Toda a escola', message text NOT NULL, send_date date, status varchar(30) NOT NULL DEFAULT 'Enviado', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_announcements_school ON announcements(school_id,send_date);
CREATE TABLE role_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL, module varchar(80) NOT NULL, action varchar(30) NOT NULL, allowed boolean NOT NULL DEFAULT false, UNIQUE(role,module,action));
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id), role user_role, module varchar(120) NOT NULL, action varchar(60) NOT NULL, summary text, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_audit_log_school ON audit_log(school_id,occurred_at DESC);

-- ================= SECRETARIA — GESTÃO ESCOLAR =================
CREATE TYPE academic_period_type AS ENUM ('ANO_LETIVO','BIMESTRE','TRIMESTRE','SEMESTRE');
CREATE TABLE academic_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(120) NOT NULL, period_type academic_period_type NOT NULL, start_date date NOT NULL, end_date date NOT NULL, school_days integer, status varchar(30) NOT NULL DEFAULT 'Planejado', CHECK(end_date >= start_date));
CREATE TABLE enrollment_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid REFERENCES students(id), student_name varchar(180) NOT NULL, request_type varchar(60) NOT NULL, request_date date NOT NULL DEFAULT CURRENT_DATE, notes text, status varchar(40) NOT NULL DEFAULT 'Em análise');
CREATE INDEX idx_enrollment_requests_school ON enrollment_requests(school_id,status);
CREATE TABLE lesson_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, teacher_id uuid REFERENCES teachers(id), title varchar(180) NOT NULL, subject varchar(120), plan_date date, content text, status varchar(30) NOT NULL DEFAULT 'Planejado');
CREATE TABLE student_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid REFERENCES students(id), student_name varchar(180), occurrence_type varchar(60), description text NOT NULL, occurrence_date date NOT NULL DEFAULT CURRENT_DATE, status varchar(30) NOT NULL DEFAULT 'Em aberto');
CREATE INDEX idx_student_occurrences_student ON student_occurrences(school_id,student_id);

-- ================= SECRETARIA — ATENDIMENTO =================
CREATE TYPE service_request_status AS ENUM ('ABERTA','EM_ANALISE','AGUARDANDO_DOCUMENTO','EM_PROCESSAMENTO','CONCLUIDA','CANCELADA');
CREATE TABLE service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, protocol varchar(40) UNIQUE NOT NULL, request_type varchar(80) NOT NULL, requester varchar(180) NOT NULL, priority varchar(20) NOT NULL DEFAULT 'Normal', due_date date, notes text, status service_request_status NOT NULL DEFAULT 'ABERTA', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_service_requests_school ON service_requests(school_id,status);
CREATE TABLE appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, with_whom varchar(80), appointment_date date NOT NULL, appointment_time varchar(10), status varchar(30) NOT NULL DEFAULT 'Agendado');
CREATE TABLE queue_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, ticket_date date NOT NULL DEFAULT CURRENT_DATE, ticket_number integer NOT NULL, ticket_type varchar(20) NOT NULL DEFAULT 'Normal', status varchar(20) NOT NULL DEFAULT 'Aguardando', UNIQUE(school_id,ticket_date,ticket_number));
CREATE TABLE contact_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, subject varchar(180) NOT NULL, channel varchar(30) NOT NULL, notes text, forwarded_to varchar(80), status varchar(30) NOT NULL DEFAULT 'Em atendimento', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_issuances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, protocol varchar(40) UNIQUE NOT NULL, student_name varchar(180) NOT NULL, doc_type varchar(80) NOT NULL, issue_date date NOT NULL DEFAULT CURRENT_DATE, notes text, issued_by uuid REFERENCES users(id));
CREATE TABLE student_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, doc_type varchar(80) NOT NULL, notes text, status varchar(30) NOT NULL DEFAULT 'Pendente');

-- ================= SERVIÇOS ESCOLARES (BIBLIOTECA, TRANSPORTE, ALIMENTAÇÃO, SAÚDE, FINANCEIRO) =================
CREATE TABLE library_loans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, borrower varchar(180), loan_date date, due_date date, status varchar(30) NOT NULL DEFAULT 'Emprestado');
CREATE TABLE transport_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(150) NOT NULL, vehicle varchar(100), driver varchar(150), monitor varchar(150), shift varchar(20), students_count integer DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'Ativa');
CREATE TABLE school_meals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title varchar(180) NOT NULL, meal_date date, restrictions text, status varchar(30) NOT NULL DEFAULT 'Planejado');
CREATE TABLE health_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, record_type varchar(60) NOT NULL, description text NOT NULL, record_date date, status varchar(30) NOT NULL DEFAULT 'Em aberto');
CREATE TABLE finance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, record_type varchar(60) NOT NULL, amount numeric(12,2) NOT NULL DEFAULT 0, due_date date, status varchar(30) NOT NULL DEFAULT 'Em aberto');
CREATE INDEX idx_finance_records_student ON finance_records(school_id,student_id,status);
